const std=@import("std");const X=@import("experimental/hydration_exchange.zig");const M=X.M;
fn donor() M.Cohort{return .{.biomass=0.12940502166748047,.organization=0.13426367938518524,.support_mass=0.017374489456415176,.optimum=296.1463928222656,.efficiency=1.0451198816299438,.structure=0.13595879077911377,.feeding=0.20643378794193268,.mobility=0.0,.relocations=0,.last_from=0,.last_to=0,.last_move_time=0.0,.lifetime_grazed=0.047025907784700394,.generation=6,.lineage=478,.parent=232,.reproduction_credit=0.005128047429025173};}

const area:f64=7669529600;
test "continuous boundary zero thin film and submergence"{for([_]f32{0,1})|h|{for([_]f32{0,0.00015,0.0002})|d|{const lo=M.effectiveHydration(h,@max(0,d-1e-9),300);const at=M.effectiveHydration(h,d,300);const hi=M.effectiveHydration(h,d+1e-9,300);try std.testing.expect(@abs(lo-at)<0.0001 and @abs(hi-at)<0.0001);}}try std.testing.expectEqual(@as(f32,0),M.effectiveHydration(1,0,270));try std.testing.expectEqual(@as(f32,0),M.effectiveHydration(1,0,355));try std.testing.expectEqual(@as(f32,0),M.effectiveHydration(1,1,300));}
test "original fixed matrix repeated actual exchange external exposure only"{
for([_]f32{3600,1800})|dt|{for(0..5)|mode|{for([_]f32{0,0.25})|r|{
 var c=M.initialized(7);c.cohorts[0]=donor();c.cohorts[0].retention_allocation=r;var liquid:f32=@floatCast(1000*area/1e9);var vapor:f32=0;var held:f64=0;var co2:f64=10;var oxygen:f64=10;const w0=X.total(c,liquid,vapor,area);const c0=co2+@as(f64,c.cohorts[0].biomass);const n0=@as(f64,c.nutrient)+@as(f64,c.cohorts[0].biomass)*M.nutrient_per_carbon;
 const ticks:usize=@intFromFloat((if(mode==4) @as(f32,30) else 7)*86400/dt);for(0..ticks)|tick|{const day=@as(f64,@floatFromInt(tick))*dt/86400;const wet=mode==0 or ((mode==1 or mode==4) and day<1) or (mode==2 and (day<1 or day>=4));if(wet)X.deposit(&liquid,&held,1e9/area) else {held+=@as(f64,liquid)*(1e9/area);liquid=0;}
 const f=X.step(&c,&liquid,&vapor,area,.{.temperature=300,.depth_km=999,.light=if(@mod(day,1)<0.5)1 else 0,.carbon_available=@floatCast(co2),.oxygen_carbon_capacity=@floatCast(oxygen)},dt).?;co2+=@as(f64,f.recycled)-f.fixed;oxygen+=@as(f64,f.fixed)-f.recycled;
 try std.testing.expect(@abs(X.total(c,liquid,vapor,area)+held-w0)<=1e-9);var carbon=co2+@as(f64,c.detritus);var n=@as(f64,c.nutrient);for(c.cohorts)|v|{carbon+=v.biomass;n+=@as(f64,v.biomass)*M.nutrient_per_carbon;}try std.testing.expect(@abs(carbon-c0)<1e-4 and @abs(n-n0)<1e-4);
 }if(mode==4)try std.testing.expect(c.cohorts[0].biomass==0 and c.cohorts[0].stored_water==0);std.debug.print("CONTINUOUS dt={d} mode={d} r={d} mass={d} water={d} residual={d}\n",.{dt,mode,r,c.cohorts[0].biomass,c.cohorts[0].stored_water,X.total(c,liquid,vapor,area)+held-w0});
}}}}
test "area scaling bounded transfer invalid atomic and ignores supplied hydration"{for([_]f64{1,7669529600,1e15})|a|{var c=M.initialized(7);c.cohorts[0]=donor();c.cohorts[0].retention_allocation=0.25;var liquid:f32=0.001;var vapor:f32=1e9;const w=X.total(c,liquid,vapor,a);_=X.step(&c,&liquid,&vapor,a,.{.temperature=300,.depth_km=0,.light=1,.carbon_available=1,.oxygen_carbon_capacity=1,.qa_hydration=.{1,1,1,1}},1800).?;try std.testing.expect(@abs(X.total(c,liquid,vapor,a)-w)<=@max(1e-9,64*std.math.floatEps(f64)*w));}var c=M.initialized(7);c.cohorts[0]=donor();var liquid:f32=0;var vapor:f32=0;const before=c;try std.testing.expect(X.step(&c,&liquid,&vapor,0,.{.temperature=300,.depth_km=0,.light=1,.carbon_available=1,.oxygen_carbon_capacity=1},1800)==null);try std.testing.expectEqualDeep(before,c);_=X.step(&c,&liquid,&vapor,area,.{.temperature=300,.depth_km=0,.light=1,.carbon_available=1,.oxygen_carbon_capacity=1,.qa_hydration=.{1,1,1,1}},1800).?;try std.testing.expect(c.cohorts[0].biomass<before.cohorts[0].biomass);try std.testing.expectEqual(@as(f64,0),M.waterTotal(c));}
test "actual funded dry versus trace film no lost internal benefit"{var masses:[2]f32=undefined;for([_]f32{0,1e-9},0..)|depth,i|{var c=M.initialized(7);c.cohorts[0]=donor();c.cohorts[0].retention_allocation=0.25;c.cohorts[0].stored_water=M.waterCapacity(c.cohorts[0]);_=M.step(&c,.{.temperature=300,.depth_km=depth,.light=1,.carbon_available=10,.oxygen_carbon_capacity=10,.qa_hydration=.{1,0,0,0}},3600);masses[i]=c.cohorts[0].biomass;}std.debug.print("CONTINUOUS_BOUNDARY dry={d} trace={d}\n",.{masses[0],masses[1]});try std.testing.expect(@abs(masses[1]-masses[0])<0.00001);}
test "disabled adapter oldfields match production actual water depth"{const P=@import("simulation/microbes.zig");for([_]f32{0,0.001,1000})|initial|{var c=M.initialized(7);c.cohorts[0]=donor();var p=P.initialized(7);inline for(std.meta.fields(P.Cohort))|f|@field(p.cohorts[0],f.name)=@field(c.cohorts[0],f.name);var liquid=initial;var vapor:f32=0;const depth:f32=@floatCast(@as(f64,initial)*(1e9/area)/1e6);const f=X.step(&c,&liquid,&vapor,area,.{.temperature=300,.depth_km=999,.light=1,.carbon_available=10,.oxygen_carbon_capacity=10},1440).?;const pf=P.step(&p,.{.temperature=300,.depth_km=depth,.light=1,.carbon_available=10,.oxygen_carbon_capacity=10},1440);inline for(std.meta.fields(P.Flux))|field|try std.testing.expectEqual(@field(pf,field.name),@field(f,field.name));for(0..4)|i|{inline for(std.meta.fields(P.Cohort))|field|try std.testing.expectEqual(@field(p.cohorts[i],field.name),@field(c.cohorts[i],field.name));}try std.testing.expectEqual(initial,liquid);}}
